(()=>{
const data=window.TERREN_DATA;let language='pl',filter='all';const isHome=document.body.dataset.page==='home';
try{language=localStorage.getItem('terren-language')==='en'?'en':'pl'}catch{}
const text=key=>data.copy[language][key];const locale=()=>language==='pl'?0:1;
const projectLink=i=>`projekt.html?id=${i}`;
function renderProjects(){const grid=document.querySelector('[data-project-grid]');if(!grid)return;const l=locale();grid.innerHTML=data.projects.map((p,i)=>({p,i})).filter(({p})=>filter==='all'||p.type===filter).map(({p,i})=>`<a class="gallery-card" href="${projectLink(i)}"><div class="gallery-image"><img src="assets/${p.image}" alt="${p.city[l]} — ${p.desc[l]}" width="1536" height="1024" loading="lazy"><span>${text('concept')}</span></div><h2>${p.city[l]}</h2><p>${p.desc[l]}</p></a>`).join('');}
function selectedIndex(size){const parsed=Number(new URL(location.href).searchParams.get('id'));return Number.isInteger(parsed)&&parsed>=0&&parsed<size?parsed:0;}
function renderDetail(){const node=document.querySelector('[data-project-detail]');if(!node)return;const i=selectedIndex(data.projects.length),p=data.projects[i],next=data.projects[(i+1)%data.projects.length],l=locale();document.title=`TERREN — ${p.city[l]}`;node.innerHTML=`<div class="detail-heading"><a href="projekty.html">${text('projectBack')}</a><h1>${p.city[l]}</h1><p>${p.desc[l]}</p></div><figure class="detail-image"><img src="assets/${p.image}" alt="${p.city[l]}" width="1536" height="1024"><figcaption>${text('concept')} / TERREN</figcaption></figure><section class="detail-copy"><h2>${text('projectAbout')}</h2><div><p>${p.text[l]}</p><p class="page-demo">${text('demo')}</p></div></section><a class="next-project" href="${projectLink((i+1)%data.projects.length)}"><span>${text('projectOther')}</span><strong>${next.city[l]}</strong><span>↗</span></a>`;}
function renderServices(){const node=document.querySelector('[data-services]');if(!node)return;const l=locale();node.innerHTML=data.services.map((s,i)=>`<article class="service-block"><figure><img src="assets/${s.image}" alt="${s.title[l]}" width="1536" height="1024" loading="lazy"></figure><div class="service-copy"><span class="service-index">0${i+1} / TERREN</span><h2>${s.title[l]}</h2><p>${s.text[l]}</p><span class="section-eyebrow">${text('scope')}</span><ul>${s.items[l].map(item=>`<li>${item}</li>`).join('')}</ul><a class="underlined-link" href="kontakt.html">${text('talk')}</a></div></article>`).join('');}
function renderArticles(){const node=document.querySelector('[data-articles]');if(!node)return;const l=locale();node.innerHTML=data.articles.map((a,i)=>`<a class="journal-card" href="artykul.html?id=${i}"><img src="assets/${a.image}" alt="${a.title[l]}" width="1536" height="1024" loading="lazy"><h2>${a.title[l]}</h2><p>${a.intro[l]}</p><span>${text('read')}</span></a>`).join('');}
function renderArticle(){const node=document.querySelector('[data-article-detail]');if(!node)return;const a=data.articles[selectedIndex(data.articles.length)],l=locale();document.title=`TERREN — ${a.title[l]}`;node.innerHTML=`<div class="article-heading"><a href="inspiracje.html">${text('articleBack')}</a><h1>${a.title[l]}</h1><p>${a.intro[l]}</p></div><img src="assets/${a.image}" alt="${a.title[l]}" width="1536" height="1024"><div class="article-body">${a.body[l].map(p=>`<p>${p}</p>`).join('')}</div>`;}
function setLanguage(next){language=next==='en'?'en':'pl';document.documentElement.lang=language;document.querySelector('.menu-close')?.setAttribute('aria-label',text('close'));document.querySelector('.project-filters')?.setAttribute('aria-label',language==='pl'?'Kategorie':'Categories');document.querySelectorAll('[data-page-copy]').forEach(el=>el.textContent=text(el.dataset.pageCopy));document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===language)));if(!isHome){document.querySelectorAll('.status').forEach(el=>el.textContent='');const titleKey={projekty:'projectsTitle',oferta:'offerTitle',studio:'studioTitle',kontakt:'contactTitle',inspiracje:'journalTitle'}[document.body.dataset.page];if(titleKey)document.title=`TERREN — ${text(titleKey)}`;}renderProjects();renderDetail();renderServices();renderArticles();renderArticle();try{localStorage.setItem('terren-language',language)}catch{}}
const menuMarkup=`<dialog class="site-menu" id="site-menu" aria-labelledby="menu-title"><button class="menu-close" aria-label="Close">×</button><a class="menu-brand" href="index.html"><img src="assets/terren-logo.png" alt="TERREN" width="2172" height="724"></a><p id="menu-title" data-page-copy="menu">Menu</p><nav class="menu-links"><a href="index.html" data-page-copy="navHome">START</a><a href="projekty.html" data-page-copy="navProjects">PROJEKTY</a><a href="oferta.html" data-page-copy="navOffer">OFERTA</a><a href="studio.html" data-page-copy="navStudio">STUDIO</a><a href="kontakt.html" data-page-copy="navContact">KONTAKT</a><a href="inspiracje.html" data-page-copy="navJournal">INSPIRACJE</a></nav></dialog>`;
document.body.insertAdjacentHTML('beforeend',menuMarkup);
const parent=isHome?document.querySelector('.hero'):document.querySelector('.page-header');parent.insertAdjacentHTML('beforeend','<button class="site-menu-toggle" aria-label="Menu" aria-controls="site-menu" aria-expanded="false"><span></span><span></span></button>');
const menu=document.querySelector('#site-menu'),button=document.querySelector('.site-menu-toggle');button.addEventListener('click',()=>{menu.showModal();button.setAttribute('aria-expanded','true');document.body.style.overflow='hidden'});menu.querySelector('.menu-close').addEventListener('click',()=>menu.close());menu.addEventListener('close',()=>{button.setAttribute('aria-expanded','false');document.body.style.overflow=''});
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(other=>{const selected=other===b;other.classList.toggle('active',selected);other.setAttribute('aria-pressed',String(selected))});renderProjects()}));
if(!isHome){const form=document.querySelector('#contact-form');form?.addEventListener('submit',e=>{e.preventDefault();document.querySelector('.status').textContent=text('formDemo')});}
setLanguage(language);
})();

